// I/O: path string (caller) > Spec pointer or null; render(spec) > HTML bytes (caller frees)
// ===================================================================
const std = @import("std");
pub const Box = struct { lab: []const u8, init: []const u8 = "" };
pub const Combo = struct { lab: []const u8, opts: []const []const u8 };
pub const Hov = struct { lab: []const u8, items: []const []const u8 };
pub const Item = struct { name: []const u8, btns: []const []const u8 = &.{}, box: []const u8 = "" };
pub const Link = struct { href: []const u8, lab: []const u8, text: []const u8 };
pub const Spec = struct { path: []const u8, pre: bool = true, title: []const u8, btns: []const []const u8 = &.{}, boxes: []const Box = &.{}, combos: []const Combo = &.{}, togs: []const []const u8 = &.{}, hovs: []const Hov = &.{}, items: []const Item = &.{}, links: []const Link = &.{}, popup: bool = false, file: bool = false };
